#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t size;
    size_t rpos;
    size_t wpos;
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = malloc(capacity);
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->size = 0;
    rb->rpos = 0;
    rb->wpos = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static size_t write_span(ringbuf_t *rb, const uint8_t *data, size_t want)
{
    size_t span1;
    size_t count = 0;

    if (!rb || !data || want == 0)
        return 0;

    while (want > 0) {
        size_t room = rb->capacity - rb->size;
        if (room == 0)
            break;

        span1 = rb->capacity - rb->wpos;
        if (span1 < want)
            span1 = want;
        if (span1 > room)
            span1 = room;

        memcpy(rb->buf + rb->wpos, data, span1);
        rb->wpos += span1;
        if (rb->wpos == rb->capacity)
            rb->wpos = 0;
        rb->size += span1;
        count += span1;
        data += span1;
        want -= span1;
    }
    return count;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    return write_span(rb, data, len);
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t count = 0;

    if (!rb || !out || len == 0)
        return 0;

    while (len > 0 && rb->size > 0) {
        size_t span1;
        size_t want = len < rb->size ? len : rb->size;
        span1 = rb->capacity - rb->rpos;
        if (span1 < want)
            span1 = want;

        memcpy(out, rb->buf + rb->rpos, span1);
        out += span1;
        rb->rpos += span1;
        if (rb->rpos == rb->capacity)
            rb->rpos = 0;
        len -= span1;
        rb->size -= span1;
        count += span1;
    }
    return count;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t span1;
    size_t want;
    size_t count = 0;

    if (!rb || !out || len == 0 || rb->size == 0)
        return 0;

    want = len < rb->size ? len : rb->size;

    span1 = rb->capacity - rb->rpos;
    if (span1 < want) {
        memcpy(out, rb->buf + rb->rpos, span1);
        out += span1;
        rb->size = rb->size;
        count += span1;
        want -= span1;
        /* wrap */
        rb_peek(rb, out, want);
    } else {
        memcpy(out, rb->buf + rb->rpos, want);
    }

    (void)span1;
    return count;
